-- PM-2: technical specifications and product images (product master, platform-wide).
--
-- Runs as dp_owner (ADR-012A). Additive only: one enum, three new tables, CHECK constraints and
-- guard triggers; no existing table, column or row changes. Image bytes are NOT stored here:
-- the media storage holds them under random keys, this database only the metadata. Prisma's
-- drift check sees the tables and the partial unique index (one cover per product); the CHECK
-- constraints and triggers are tested in test/integration/catalog.int.test.ts.
--
-- Part 1 is generated by `prisma migrate diff --from-schema <main> --to-schema schema.prisma`.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dp_app') THEN
    RAISE EXCEPTION 'PM-2: database role dp_app missing; ADR-012A must be applied first';
  END IF;
END $$;

-- ===========================================================================================
-- Part 1: tables and indexes (generated)
-- ===========================================================================================
-- CreateEnum
CREATE TYPE "SpecDataType" AS ENUM ('NUMBER', 'TEXT', 'BOOLEAN', 'RANGE');

-- CreateTable
CREATE TABLE "SpecDefinition" (
    "id" UUID NOT NULL,
    "key" VARCHAR(64) NOT NULL,
    "name" VARCHAR(120) NOT NULL,
    "dataType" "SpecDataType" NOT NULL,
    "units" VARCHAR(32)[] DEFAULT ARRAY[]::VARCHAR(32)[],
    "testMethods" VARCHAR(64)[] DEFAULT ARRAY[]::VARCHAR(64)[],
    "required" BOOLEAN NOT NULL DEFAULT false,
    "minValue" DECIMAL(20,6),
    "maxValue" DECIMAL(20,6),
    "decimals" INTEGER,
    "maxLength" INTEGER,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "archived" BOOLEAN NOT NULL DEFAULT false,
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "SpecDefinition_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ProductSpecValue" (
    "id" UUID NOT NULL,
    "productId" UUID NOT NULL,
    "definitionId" UUID NOT NULL,
    "numberValue" DECIMAL(20,6),
    "rangeMin" DECIMAL(20,6),
    "rangeMax" DECIMAL(20,6),
    "textValue" VARCHAR(2000),
    "booleanValue" BOOLEAN,
    "unit" VARCHAR(32),
    "testMethod" VARCHAR(64),
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "ProductSpecValue_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ProductImage" (
    "id" UUID NOT NULL,
    "productId" UUID NOT NULL,
    "storageKey" VARCHAR(200) NOT NULL,
    "mimeType" VARCHAR(32) NOT NULL,
    "byteSize" INTEGER NOT NULL,
    "width" INTEGER NOT NULL,
    "height" INTEGER NOT NULL,
    "sha256" CHAR(64) NOT NULL,
    "originalFilename" VARCHAR(255) NOT NULL,
    "altText" VARCHAR(300),
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "isCover" BOOLEAN NOT NULL DEFAULT false,
    "variants" JSONB NOT NULL DEFAULT '{}',
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "ProductImage_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "SpecDefinition_key_key" ON "SpecDefinition"("key");

-- CreateIndex
CREATE INDEX "SpecDefinition_archived_sortOrder_idx" ON "SpecDefinition"("archived", "sortOrder");

-- CreateIndex
CREATE INDEX "ProductSpecValue_definitionId_idx" ON "ProductSpecValue"("definitionId");

-- CreateIndex
CREATE UNIQUE INDEX "ProductSpecValue_productId_definitionId_key" ON "ProductSpecValue"("productId", "definitionId");

-- CreateIndex
CREATE UNIQUE INDEX "ProductImage_storageKey_key" ON "ProductImage"("storageKey");

-- CreateIndex
CREATE INDEX "ProductImage_productId_sortOrder_idx" ON "ProductImage"("productId", "sortOrder");

-- CreateIndex
CREATE UNIQUE INDEX "ProductImage_cover_productId_key" ON "ProductImage"("productId") WHERE ("isCover");

-- AddForeignKey
ALTER TABLE "ProductSpecValue" ADD CONSTRAINT "ProductSpecValue_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductSpecValue" ADD CONSTRAINT "ProductSpecValue_definitionId_fkey" FOREIGN KEY ("definitionId") REFERENCES "SpecDefinition"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductImage" ADD CONSTRAINT "ProductImage_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ===========================================================================================
-- Part 2: rules Prisma cannot model
-- ===========================================================================================

ALTER TABLE "SpecDefinition"
  ADD CONSTRAINT "SpecDefinition_key_format" CHECK ("key" ~ '^[a-z][a-z0-9_]{1,63}$'),
  ADD CONSTRAINT "SpecDefinition_name_trimmed" CHECK ("name" = btrim("name") AND "name" <> ''),
  ADD CONSTRAINT "SpecDefinition_numeric_rules" CHECK (
    "dataType" IN ('NUMBER', 'RANGE')
    OR ("minValue" IS NULL AND "maxValue" IS NULL AND "decimals" IS NULL AND cardinality("units") = 0)),
  ADD CONSTRAINT "SpecDefinition_text_rules" CHECK ("dataType" = 'TEXT' OR "maxLength" IS NULL),
  ADD CONSTRAINT "SpecDefinition_bounds_order" CHECK ("minValue" IS NULL OR "maxValue" IS NULL OR "minValue" <= "maxValue"),
  ADD CONSTRAINT "SpecDefinition_decimals_range" CHECK ("decimals" IS NULL OR "decimals" BETWEEN 0 AND 6),
  ADD CONSTRAINT "SpecDefinition_max_length_range" CHECK ("maxLength" IS NULL OR "maxLength" BETWEEN 1 AND 2000),
  ADD CONSTRAINT "SpecDefinition_units_count" CHECK (cardinality("units") <= 8 AND cardinality("testMethods") <= 8),
  ADD CONSTRAINT "SpecDefinition_version_positive" CHECK ("version" >= 1);

-- Exactly one value shape; the trigger below ties it to the definition's data type.
ALTER TABLE "ProductSpecValue"
  ADD CONSTRAINT "ProductSpecValue_one_shape" CHECK (
    (CASE WHEN "numberValue" IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN "rangeMin" IS NOT NULL OR "rangeMax" IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN "textValue" IS NOT NULL THEN 1 ELSE 0 END)
    + (CASE WHEN "booleanValue" IS NOT NULL THEN 1 ELSE 0 END) = 1),
  ADD CONSTRAINT "ProductSpecValue_range_complete" CHECK (("rangeMin" IS NULL) = ("rangeMax" IS NULL)),
  ADD CONSTRAINT "ProductSpecValue_range_order" CHECK ("rangeMin" IS NULL OR "rangeMin" <= "rangeMax"),
  ADD CONSTRAINT "ProductSpecValue_text_trimmed" CHECK ("textValue" IS NULL OR ("textValue" = btrim("textValue") AND "textValue" <> ''));

CREATE FUNCTION catalog_spec_value_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  def "SpecDefinition"%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW."productId" IS DISTINCT FROM OLD."productId"
                           OR NEW."definitionId" IS DISTINCT FROM OLD."definitionId") THEN
    RAISE EXCEPTION 'catalog: a specification value cannot move to another product or definition'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO def FROM "SpecDefinition" WHERE "id" = NEW."definitionId";
  IF (def."dataType" = 'NUMBER' AND NEW."numberValue" IS NULL)
     OR (def."dataType" = 'RANGE' AND NEW."rangeMin" IS NULL)
     OR (def."dataType" = 'TEXT' AND NEW."textValue" IS NULL)
     OR (def."dataType" = 'BOOLEAN' AND NEW."booleanValue" IS NULL) THEN
    RAISE EXCEPTION 'catalog: the value does not match the specification data type'
      USING ERRCODE = 'check_violation';
  END IF;
  IF cardinality(def."units") = 0 AND NEW."unit" IS NOT NULL
     OR cardinality(def."units") > 0 AND (NEW."unit" IS NULL OR NOT NEW."unit" = ANY (def."units")) THEN
    RAISE EXCEPTION 'catalog: the unit is not accepted by the specification'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "ProductSpecValue_guard" BEFORE INSERT OR UPDATE ON "ProductSpecValue"
  FOR EACH ROW EXECUTE FUNCTION catalog_spec_value_guard();

-- Key and data type of a definition never change: stored values depend on them.
CREATE FUNCTION catalog_spec_definition_immutable() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."key" IS DISTINCT FROM OLD."key" OR NEW."dataType" IS DISTINCT FROM OLD."dataType" THEN
    RAISE EXCEPTION 'catalog: a specification key and data type cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "SpecDefinition_immutable" BEFORE UPDATE ON "SpecDefinition"
  FOR EACH ROW EXECUTE FUNCTION catalog_spec_definition_immutable();

ALTER TABLE "ProductImage"
  ADD CONSTRAINT "ProductImage_storage_key_format" CHECK ("storageKey" ~ '^products/[0-9a-f]{32}/original$'),
  ADD CONSTRAINT "ProductImage_mime_type" CHECK ("mimeType" IN ('image/jpeg', 'image/png', 'image/webp')),
  ADD CONSTRAINT "ProductImage_byte_size" CHECK ("byteSize" BETWEEN 1 AND 10485760),
  ADD CONSTRAINT "ProductImage_dimensions" CHECK ("width" >= 800 AND "height" >= 600 AND "width"::bigint * "height" <= 25000000),
  ADD CONSTRAINT "ProductImage_sha256_format" CHECK ("sha256" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "ProductImage_filename_safe" CHECK ("originalFilename" <> '' AND "originalFilename" !~ '[/\\[:cntrl:]]'),
  ADD CONSTRAINT "ProductImage_alt_trimmed" CHECK ("altText" IS NULL OR ("altText" = btrim("altText") AND "altText" <> '')),
  ADD CONSTRAINT "ProductImage_version_positive" CHECK ("version" >= 1);

-- The file facts of an image never change; a different file is a new image.
CREATE FUNCTION catalog_image_immutable() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW."productId" IS DISTINCT FROM OLD."productId"
     OR NEW."storageKey" IS DISTINCT FROM OLD."storageKey"
     OR NEW."sha256" IS DISTINCT FROM OLD."sha256"
     OR NEW."mimeType" IS DISTINCT FROM OLD."mimeType"
     OR NEW."byteSize" IS DISTINCT FROM OLD."byteSize"
     OR NEW."width" IS DISTINCT FROM OLD."width"
     OR NEW."height" IS DISTINCT FROM OLD."height" THEN
    RAISE EXCEPTION 'catalog: the file facts of an image cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "ProductImage_immutable" BEFORE UPDATE ON "ProductImage"
  FOR EACH ROW EXECUTE FUNCTION catalog_image_immutable();

-- Privileges: ADR-012A default privileges give dp_app full DML on the new tables. Values and
-- images are deleted by the API (replace and remove); unused definitions may be deleted too, a
-- definition in use is protected by its foreign key.
